CREATE TABLE fuel_types(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(30) NOT NULL UNIQUE,name VARCHAR(100) NOT NULL,unit VARCHAR(10) NOT NULL DEFAULT 'L',status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE fuel_suppliers(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,supplier_id INT UNSIGNED NOT NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,UNIQUE KEY uq_fl_supplier(supplier_id),CONSTRAINT fk_fl_supplier FOREIGN KEY(supplier_id) REFERENCES suppliers(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE logistics_assets(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,site_id INT UNSIGNED NOT NULL,truck_id INT UNSIGNED NULL,machine_id INT UNSIGNED NULL,code VARCHAR(50) NOT NULL UNIQUE,name VARCHAR(150) NOT NULL,asset_type ENUM('vehicle','machine','equipment') NOT NULL,meter_type ENUM('odometer','hour_meter') NOT NULL,current_meter DECIMAL(14,2) NOT NULL DEFAULT 0,status ENUM('active','inactive','maintenance') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP NULL DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,UNIQUE KEY uq_fl_asset_truck(truck_id),UNIQUE KEY uq_fl_asset_machine(machine_id),KEY idx_fl_asset_site(site_id,status),CONSTRAINT fk_fl_asset_site FOREIGN KEY(site_id) REFERENCES sites(id),CONSTRAINT fk_fl_asset_truck FOREIGN KEY(truck_id) REFERENCES trucks(id),CONSTRAINT fk_fl_asset_machine FOREIGN KEY(machine_id) REFERENCES machines(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE logistics_people(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,site_id INT UNSIGNED NOT NULL,user_id INT UNSIGNED NULL,code VARCHAR(50) NOT NULL UNIQUE,name VARCHAR(150) NOT NULL,person_type ENUM('driver','operator') NOT NULL,license_number VARCHAR(80) NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,KEY idx_fl_person_site(site_id,status),CONSTRAINT fk_fl_person_site FOREIGN KEY(site_id) REFERENCES sites(id),CONSTRAINT fk_fl_person_user FOREIGN KEY(user_id) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE fuel_stocks(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,site_id INT UNSIGNED NOT NULL,fuel_type_id INT UNSIGNED NOT NULL,physical_quantity DECIMAL(14,3) NOT NULL DEFAULT 0,reserved_quantity DECIMAL(14,3) NOT NULL DEFAULT 0,average_unit_cost DECIMAL(16,4) NOT NULL DEFAULT 0,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE KEY uq_fl_stock(site_id,fuel_type_id),CONSTRAINT fk_fl_stock_site FOREIGN KEY(site_id) REFERENCES sites(id),CONSTRAINT fk_fl_stock_type FOREIGN KEY(fuel_type_id) REFERENCES fuel_types(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE fuel_purchase_orders(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,site_id INT UNSIGNED NOT NULL,cost_center_id INT UNSIGNED NOT NULL,fuel_supplier_id INT UNSIGNED NOT NULL,order_number VARCHAR(100) NOT NULL UNIQUE,status ENUM('draft','submitted','approved','partially_received','received','cancelled') NOT NULL DEFAULT 'draft',ordered_at DATETIME NOT NULL,created_by INT UNSIGNED NOT NULL,approved_by INT UNSIGNED NULL,approved_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,KEY idx_fl_po_site(site_id,status),CONSTRAINT fk_fl_po_site FOREIGN KEY(site_id) REFERENCES sites(id),CONSTRAINT fk_fl_po_center FOREIGN KEY(cost_center_id) REFERENCES cost_centers(id),CONSTRAINT fk_fl_po_supplier FOREIGN KEY(fuel_supplier_id) REFERENCES fuel_suppliers(id),CONSTRAINT fk_fl_po_creator FOREIGN KEY(created_by) REFERENCES users(id),CONSTRAINT fk_fl_po_approver FOREIGN KEY(approved_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE fuel_purchase_order_lines(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,purchase_order_id BIGINT UNSIGNED NOT NULL,fuel_type_id INT UNSIGNED NOT NULL,ordered_quantity DECIMAL(14,3) NOT NULL,received_quantity DECIMAL(14,3) NOT NULL DEFAULT 0,unit_cost DECIMAL(16,4) NOT NULL,UNIQUE KEY uq_fl_po_line(purchase_order_id,fuel_type_id),CONSTRAINT fk_fl_pol_order FOREIGN KEY(purchase_order_id) REFERENCES fuel_purchase_orders(id),CONSTRAINT fk_fl_pol_type FOREIGN KEY(fuel_type_id) REFERENCES fuel_types(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE fuel_receipts(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,purchase_order_id BIGINT UNSIGNED NOT NULL,receipt_number VARCHAR(100) NOT NULL UNIQUE,idempotency_key VARCHAR(100) NOT NULL UNIQUE,received_at DATETIME NOT NULL,status ENUM('received','cancelled') NOT NULL DEFAULT 'received',received_by INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_fl_receipt_order FOREIGN KEY(purchase_order_id) REFERENCES fuel_purchase_orders(id),CONSTRAINT fk_fl_receipt_user FOREIGN KEY(received_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE fuel_receipt_lines(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,receipt_id BIGINT UNSIGNED NOT NULL,purchase_order_line_id BIGINT UNSIGNED NOT NULL,quantity DECIMAL(14,3) NOT NULL,unit_cost DECIMAL(16,4) NOT NULL,CONSTRAINT fk_fl_rl_receipt FOREIGN KEY(receipt_id) REFERENCES fuel_receipts(id),CONSTRAINT fk_fl_rl_line FOREIGN KEY(purchase_order_line_id) REFERENCES fuel_purchase_order_lines(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE fuel_consumption_norms(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,asset_id INT UNSIGNED NOT NULL,fuel_type_id INT UNSIGNED NOT NULL,basis ENUM('km','hour') NOT NULL,rate DECIMAL(12,4) NOT NULL,tolerance_percent DECIMAL(7,2) NOT NULL DEFAULT 10,effective_from DATE NOT NULL,effective_to DATE NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_by INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,KEY idx_fl_norm(asset_id,fuel_type_id,effective_from,status),CONSTRAINT fk_fl_norm_asset FOREIGN KEY(asset_id) REFERENCES logistics_assets(id),CONSTRAINT fk_fl_norm_type FOREIGN KEY(fuel_type_id) REFERENCES fuel_types(id),CONSTRAINT fk_fl_norm_user FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE logistics_routes(id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY,code VARCHAR(50) NOT NULL UNIQUE,name VARCHAR(150) NOT NULL,origin_site_id INT UNSIGNED NULL,destination_site_id INT UNSIGNED NULL,planned_distance_km DECIMAL(12,2) NULL,status ENUM('active','inactive') NOT NULL DEFAULT 'active',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,CONSTRAINT fk_fl_route_origin FOREIGN KEY(origin_site_id) REFERENCES sites(id),CONSTRAINT fk_fl_route_dest FOREIGN KEY(destination_site_id) REFERENCES sites(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE logistics_missions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ordering_site_id INT UNSIGNED NOT NULL,cost_center_id INT UNSIGNED NOT NULL,route_id INT UNSIGNED NULL,asset_id INT UNSIGNED NOT NULL,person_id INT UNSIGNED NOT NULL,mission_number VARCHAR(100) NOT NULL UNIQUE,purpose VARCHAR(500) NOT NULL,status ENUM('draft','submitted','approved','in_progress','completed','justification_pending','settled','cancelled') NOT NULL DEFAULT 'draft',planned_start DATETIME NOT NULL,planned_end DATETIME NOT NULL,actual_start DATETIME NULL,actual_end DATETIME NULL,meter_start DECIMAL(14,2) NULL,meter_end DECIMAL(14,2) NULL,created_by INT UNSIGNED NOT NULL,approved_by INT UNSIGNED NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,KEY idx_fl_mission_site(ordering_site_id,status),CONSTRAINT fk_fl_mission_site FOREIGN KEY(ordering_site_id) REFERENCES sites(id),CONSTRAINT fk_fl_mission_center FOREIGN KEY(cost_center_id) REFERENCES cost_centers(id),CONSTRAINT fk_fl_mission_route FOREIGN KEY(route_id) REFERENCES logistics_routes(id),CONSTRAINT fk_fl_mission_asset FOREIGN KEY(asset_id) REFERENCES logistics_assets(id),CONSTRAINT fk_fl_mission_person FOREIGN KEY(person_id) REFERENCES logistics_people(id),CONSTRAINT fk_fl_mission_creator FOREIGN KEY(created_by) REFERENCES users(id),CONSTRAINT fk_fl_mission_approver FOREIGN KEY(approved_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE mission_advances(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,mission_id BIGINT UNSIGNED NOT NULL,amount DECIMAL(16,2) NOT NULL,currency VARCHAR(8) NOT NULL DEFAULT 'USD',status ENUM('issued','partially_justified','justified','settled','cancelled') NOT NULL DEFAULT 'issued',issued_at DATETIME NOT NULL,issued_by INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_fl_advance_mission FOREIGN KEY(mission_id) REFERENCES logistics_missions(id),CONSTRAINT fk_fl_advance_user FOREIGN KEY(issued_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE mission_justifications(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,advance_id BIGINT UNSIGNED NOT NULL,expense_type ENUM('fuel','toll','lodging','food','repair','other') NOT NULL,proof_reference VARCHAR(100) NOT NULL,amount DECIMAL(16,2) NOT NULL,expense_at DATETIME NOT NULL,attachment_path VARCHAR(500) NULL,created_by INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,deleted_at TIMESTAMP NULL,UNIQUE KEY uq_fl_proof(advance_id,proof_reference),CONSTRAINT fk_fl_just_advance FOREIGN KEY(advance_id) REFERENCES mission_advances(id),CONSTRAINT fk_fl_just_user FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE mission_adjustments(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,advance_id BIGINT UNSIGNED NOT NULL,adjustment_type ENUM('refund','complement') NOT NULL,amount DECIMAL(16,2) NOT NULL,reference VARCHAR(100) NOT NULL,adjusted_at DATETIME NOT NULL,created_by INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uq_fl_adjustment(advance_id,reference),CONSTRAINT fk_fl_adjust_advance FOREIGN KEY(advance_id) REFERENCES mission_advances(id),CONSTRAINT fk_fl_adjust_user FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE logistics_tolls(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,mission_id BIGINT UNSIGNED NOT NULL,route_id INT UNSIGNED NOT NULL,location VARCHAR(150) NOT NULL,amount DECIMAL(16,2) NOT NULL,paid_at DATETIME NOT NULL,proof_reference VARCHAR(100) NULL,created_by INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,CONSTRAINT fk_fl_toll_mission FOREIGN KEY(mission_id) REFERENCES logistics_missions(id),CONSTRAINT fk_fl_toll_route FOREIGN KEY(route_id) REFERENCES logistics_routes(id),CONSTRAINT fk_fl_toll_user FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE fuel_distributions(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,site_id INT UNSIGNED NOT NULL,cost_center_id INT UNSIGNED NOT NULL,fuel_type_id INT UNSIGNED NOT NULL,asset_id INT UNSIGNED NOT NULL,person_id INT UNSIGNED NOT NULL,mission_id BIGINT UNSIGNED NULL,distribution_number VARCHAR(100) NOT NULL UNIQUE,idempotency_key VARCHAR(100) NOT NULL UNIQUE,quantity DECIMAL(14,3) NOT NULL,unit_cost DECIMAL(16,4) NOT NULL,meter_before DECIMAL(14,2) NOT NULL,meter_after DECIMAL(14,2) NOT NULL,normative_quantity DECIMAL(14,3) NULL,variance_percent DECIMAL(9,2) NULL,is_abnormal TINYINT(1) NOT NULL DEFAULT 0,distributed_at DATETIME NOT NULL,created_by INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_fl_dist_site(site_id,distributed_at),KEY idx_fl_dist_asset(asset_id,distributed_at),CONSTRAINT fk_fl_dist_site FOREIGN KEY(site_id) REFERENCES sites(id),CONSTRAINT fk_fl_dist_center FOREIGN KEY(cost_center_id) REFERENCES cost_centers(id),CONSTRAINT fk_fl_dist_type FOREIGN KEY(fuel_type_id) REFERENCES fuel_types(id),CONSTRAINT fk_fl_dist_asset FOREIGN KEY(asset_id) REFERENCES logistics_assets(id),CONSTRAINT fk_fl_dist_person FOREIGN KEY(person_id) REFERENCES logistics_people(id),CONSTRAINT fk_fl_dist_mission FOREIGN KEY(mission_id) REFERENCES logistics_missions(id),CONSTRAINT fk_fl_dist_user FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE fuel_stock_movements(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,stock_id BIGINT UNSIGNED NOT NULL,movement_type ENUM('receipt','distribution','adjustment','transfer_in','transfer_out') NOT NULL,quantity DECIMAL(14,3) NOT NULL,quantity_before DECIMAL(14,3) NOT NULL,quantity_after DECIMAL(14,3) NOT NULL,unit_cost DECIMAL(16,4) NOT NULL,source_type VARCHAR(80) NOT NULL,source_id BIGINT UNSIGNED NOT NULL,effect_key VARCHAR(160) NOT NULL UNIQUE,moved_at DATETIME NOT NULL,created_by INT UNSIGNED NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,KEY idx_fl_move_stock(stock_id,moved_at),CONSTRAINT fk_fl_move_stock FOREIGN KEY(stock_id) REFERENCES fuel_stocks(id),CONSTRAINT fk_fl_move_user FOREIGN KEY(created_by) REFERENCES users(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO fuel_types(code,name) VALUES('DIESEL','Gazole / Diesel'),('GASOLINE','Essence');
INSERT IGNORE INTO permissions(component,action,description) VALUES('fuel-logistics','read','Consulter carburant et logistique'),('fuel-logistics','create','Créer achats, missions et distributions'),('fuel-logistics','validate','Valider commandes et missions'),('fuel-logistics','update','Exécuter réceptions et opérations'),('fuel-logistics','delete','Annuler les opérations'),('fuel-logistics','administer','Configurer actifs et normes');
INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.component='fuel-logistics' WHERE r.slug IN('administrateur','administrateur-systeme');
INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.component='fuel-logistics' AND p.action IN('read','create','update') WHERE r.slug IN('chauffeur-logistique','gestionnaire-stock','responsable-site','directeur-site','agent-distribution');
INSERT IGNORE INTO role_permissions(role_id,permission_id) SELECT r.id,p.id FROM roles r JOIN permissions p ON p.component='fuel-logistics' AND p.action IN('read','validate','administer') WHERE r.slug IN('directeur-general','direction','directeur-financier');
